        var next = Math.min((box.width - 32) / view.width, (box.height - 32) / view.height);
        scale = Math.max(.12, Math.min(2.5, next));
        x = (box.width - view.width * scale) / 2 - view.x * scale;
        y = (box.height - view.height * scale) / 2 - view.y * scale;
        applyTransform();
